import { absPath, resolvePath } from '#config/path.js';
import { readdir, writeFile } from 'node:fs/promises';
import nodePath from 'node:path';
import { pathToFileURL } from 'node:url';

const OUTPUT_FILE = 'docs/CORE-API.md';

const SOURCES = Object.freeze([
  { alias: '#core', directory: absPath.core },
  { alias: '#utils', directory: absPath.util },
]);

const HEADER = [
  '# Core API',
  '',
  '> Generated by `npm run api:index` from the exports of `src/core/**` and `src/utils/**`. Do not edit by hand.',
  '>',
  '> Look here before writing a new function: extend what exists instead of duplicating it.',
].join('\n');

const BRACKET_PAIRS = Object.freeze({ '(': ')', '[': ']', '{': '}' });
const QUOTES = ['\'', '"', '`'];

const FUNCTION_PREFIXES = Object.freeze({
  AsyncFunction: 'async ',
  GeneratorFunction: '*',
  AsyncGeneratorFunction: 'async *',
});

function findClosingIndex(source, openIndex) {
  const stack = [];
  let quote = null;

  for (let index = openIndex; index < source.length; index += 1) {
    const char = source[index];

    if (quote) {
      if (char === '\\') {
        index += 1;
      } else if (char === quote) {
        quote = null;
      }
    } else if (QUOTES.includes(char)) {
      quote = char;
    } else if (BRACKET_PAIRS[char]) {
      stack.push(BRACKET_PAIRS[char]);
    } else if (char === stack.at(-1)) {
      stack.pop();

      if (!stack.length) {
        return index;
      }
    }
  }

  return -1;
}

function getParameters(fn) {
  const source = fn.toString();
  const openIndex = source.indexOf('(');
  const closeIndex = findClosingIndex(source, openIndex);

  if (openIndex === -1 || closeIndex === -1) {
    throw new Error(`Cannot read the parameters of ${fn.name}()`);
  }

  return source
    .slice(openIndex + 1, closeIndex)
    .replace(/\s+/g, ' ')
    .replace(/,\s*\}/g, ' }')
    .replace(/,\s*([\])])/g, '$1')
    .replace(/,\s*$/, '')
    .trim();
}

function isClass(value) {
  return typeof value === 'function' && /^class\s/.test(value.toString());
}

function describeExport(name, value) {
  if (isClass(value)) {
    return `class ${name}`;
  }

  if (typeof value === 'function') {
    const prefix = FUNCTION_PREFIXES[value.constructor.name] ?? '';

    return `${prefix}${name}(${getParameters(value)})`;
  }

  return name;
}

async function describeModule({ alias, directory }, file) {
  const exports = await import(pathToFileURL(nodePath.join(directory, file)).href);
  const lines = Object.entries(exports).map(([name, value]) => `- \`${describeExport(name, value)}\``);

  return { specifier: `${alias}/${file}`, lines };
}

async function describeSource(source) {
  const entries = await readdir(source.directory, { recursive: true });

  // POSIX separators before sorting: "\" and "/" sort differently against other characters,
  // and the output must not depend on the OS it was generated on.
  const files = entries
    .filter((file) => file.endsWith('.js'))
    .map((file) => file.split(nodePath.sep).join('/'))
    .sort();

  return Promise.all(files.map((file) => describeModule(source, file)));
}

export async function renderApiIndex(sources = SOURCES) {
  const modules = (await Promise.all(sources.map(describeSource)))
    .flat()
    .filter((module) => module.lines.length);

  const sections = modules.map(({ specifier, lines }) => [`## ${specifier}`, '', ...lines].join('\n'));

  return `${[HEADER, ...sections].join('\n\n')}\n`;
}

if (import.meta.main) {
  await writeFile(resolvePath(OUTPUT_FILE), await renderApiIndex());

  console.log(`✅ ${OUTPUT_FILE} is up to date`);
}
